import click
from click.testing import CliRunner
r = CliRunner()

def show(name, cmd, args, env):
    res = r.invoke(cmd, args, env=env)
    print(f"{name}: exit={res.exit_code} out={res.output!r} exc={res.exception!r}")

# 1 argument with envvar, no default
@click.command()
@click.argument("arg", envvar="X")
def c1(arg): click.echo(f"arg={arg!r}")
show("arg envvar", c1, [], {"X": "value"})
show("arg envvar empty", c1, [], {"X": ""})
show("arg no envvar", c1, [], {})

# 2 argument with envvar and default
@click.command()
@click.argument("arg", envvar="X", default="d")
def c2(arg): click.echo(f"arg={arg!r}")
show("arg envvar+default", c2, [], {"X": "value"})

# 3 non-bool flag with flag_value and envvar
@click.command()
@click.option("--upper", "trans", flag_value="upper", envvar="TRANS")
def c3(trans): click.echo(f"trans={trans!r}")
show("flag_value envvar", c3, [], {"TRANS": "1"})
show("flag_value envvar=upper", c3, [], {"TRANS": "upper"})
show("flag_value no envvar", c3, [], {})
show("flag_value cmdline", c3, ["--upper"], {})

# 4 bool flag with envvar
@click.command()
@click.option("--shout", is_flag=True, envvar="SHOUT")
def c4(shout): click.echo(f"shout={shout!r}")
show("bool flag envvar 1", c4, [], {"SHOUT": "1"})
show("bool flag envvar 0", c4, [], {"SHOUT": "0"})
show("bool flag envvar empty", c4, [], {"SHOUT": ""})
